{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    # Validate
    if not isinstance(budget, int):
        raise ValueError('Budget must be an integer')
    total_min = 0
    total_cap = 0
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError('Segment missing required field')
        total_min += s['minimum']
        total_cap += s['capacity']
    if budget < total_min:
        raise ValueError('Budget less than sum of minimums')
    if budget > total_cap:
        raise ValueError('Budget exceeds total capacity')
    # Initialize allocations
    alloc = {}
    for s in segments:
        alloc[s['name']] = s['minimum']
    remaining = budget - total_min
    # Greedy allocation
    while remaining > 0:
        best_idx = None
        best_imp = None
        best_den = None
        for i, s in enumerate(segments):
            name = s['name']
            cur = alloc[name]
            if cur < s['capacity']:
                imp = s['importance']
                den = cur + 1
                if best_idx is None:
                    best_idx = i
                    best_imp = imp
                    best_den = den
                else:
                    left = imp * best_den
                    right = best_imp * den
                    if left > right or (left == right and i < best_idx):
                        best_idx = i
                        best_imp = imp
                        best_den = den
        if best_idx is None:
            raise ValueError('Cannot allocate remaining budget (should not happen)')
        name = segments[best_idx]['name']
        alloc[name] += 1
        remaining -= 1
    total_allocated = sum(alloc.values())
    return {
        'allocations': alloc,
        'segment_order': [s['name'] for s in segments],
        'total_allocated': total_allocated
    }"}
